CREATE TABLE IF NOT EXISTS admins(id SERIAL PRIMARY KEY,username TEXT UNIQUE NOT NULL,password_hash TEXT NOT NULL,role TEXT DEFAULT 'admin',created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS site_content(key TEXT PRIMARY KEY,value TEXT NOT NULL DEFAULT '');
CREATE TABLE IF NOT EXISTS decor_items(id SERIAL PRIMARY KEY,title TEXT NOT NULL,category TEXT NOT NULL,description TEXT DEFAULT '',image_url TEXT NOT NULL,featured BOOLEAN DEFAULT false,active BOOLEAN DEFAULT true,sort_order INT DEFAULT 0,created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS services(id SERIAL PRIMARY KEY,title TEXT NOT NULL,description TEXT DEFAULT '',icon TEXT DEFAULT '♡',active BOOLEAN DEFAULT true,sort_order INT DEFAULT 0);
CREATE TABLE IF NOT EXISTS reservations(id SERIAL PRIMARY KEY,name TEXT NOT NULL,phone TEXT NOT NULL,event_type TEXT NOT NULL,event_date DATE NOT NULL,location TEXT DEFAULT '',budget TEXT DEFAULT '',message TEXT DEFAULT '',status TEXT DEFAULT 'Yeni',admin_note TEXT DEFAULT '',created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS reviews(id SERIAL PRIMARY KEY,name TEXT NOT NULL,text TEXT NOT NULL,rating INT DEFAULT 5,active BOOLEAN DEFAULT true,created_at TIMESTAMPTZ DEFAULT now());
